bool solve(string& s) {
    int n = s.size();
    int lo = 0, hi = n - 1;
    for (int i = 0; i < n; i++) {
        char c = 'a' + i;
        if (s[lo] == c) lo++;
        else if (s[hi] == c) hi--;
        else return false;
    }
    return true;
}

string solve(int x) {
    if (x > 45) return "-1";
    string res;
    for (int d = 9; d >= 1 && x > 0; d--) {
        if (x >= d) { res += ('0' + d); x -= d; }
        else { res += ('0' + x); x = 0; }
    }
    reverse(res.begin(), res.end());
    return res;
}

