struct SegTree {
    int n;
    vector<int> t;
    SegTree(int n) : n(n), t(4*n, 0) {}
    void update(int v, int tl, int tr, int pos, int val) {
        if (tl == tr) { t[v] = max(t[v], val); return; }
        int tm = (tl+tr)/2;
        if (pos <= tm) update(2*v, tl, tm, pos, val);
        else update(2*v+1, tm+1, tr, pos, val);
        t[v] = max(t[2*v], t[2*v+1]);
    }
    int query(int v, int tl, int tr, int l, int r) {
        if (l > r) return 0;
        if (l == tl && r == tr) return t[v];
        int tm = (tl+tr)/2;
        return max(query(2*v, tl, tm, l, min(r,tm)),
                   query(2*v+1, tm+1, tr, max(l,tm+1), r));
    }
};

void solve() {
    int n; cin >> n;
    vector<long long> a(n);
    vector<int> idx(n);
    for (int i = 0; i < n; i++) { cin >> a[i]; idx[i] = i; }
    sort(idx.begin(), idx.end(), [&](int x, int y) { return a[x] < a[y]; });
    sort(a.begin(), a.end());

    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) prefix[i+1] = prefix[i] + a[i];

    vector<int> ans(n);
    for (int i = 0; i < n; i++) {
        int lo = i, hi = n - 1, best = i;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (prefix[mid+1] - prefix[i] <= 2 * a[i]) {
                best = mid;
                lo = mid + 1;
            } else hi = mid - 1;
        }
        ans[i] = best;
    }
}

vector<int> minInterval(vector<vector<int>>& intervals, vector<int>& queries) {
    int n = intervals.size(), q = queries.size();
    sort(intervals.begin(), intervals.end());
    vector<int> qi(q);
    iota(qi.begin(), qi.end(), 0);
    sort(qi.begin(), qi.end(), [&](int a, int b) { return queries[a] < queries[b]; });

    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
    vector<int> res(q, -1);
    int j = 0;
    for (int i : qi) {
        while (j < n && intervals[j][0] <= queries[i]) {
            int len = intervals[j][1] - intervals[j][0] + 1;
            pq.push({len, intervals[j][1]});
            j++;
        }
        while (!pq.empty() && pq.top().second < queries[i]) pq.pop();
        if (!pq.empty()) res[i] = pq.top().first;
    }
    return res;
}

long long solve(vector<int>& a) {
    int n = a.size();
    vector<long long> suffix(n + 1, 0);
    for (int i = n - 1; i >= 0; i--)
        suffix[i] = suffix[i + 1] + a[i];

    long long ans = suffix[0];  // must include first segment
    for (int i = 1; i < n; i++)
        if (suffix[i] > 0) ans += suffix[i];
    return ans;
}
